import{_ as l,a0 as p,w as r,s as o,ao as d,I as t,x as a,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Ubuntu 18.04 服務器上安裝和配置 KVM | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 18.04 服務器上安裝和配置 KVM | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 18.04 服務器上安裝和配置 KVM | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 18.04 服務器上安裝和配置 KVM | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180521 How to Install and Configure KVM on Ubuntu 18.04 LTS Server","title":"如何在 Ubuntu 18.04 服務器上安裝和配置 KVM","tag":"201806","desc":""},"relativePath":"201806/20180521 How to Install and Configure KVM on Ubuntu 18.04 LTS Server.md","filePath":"[post].md"}'),u={name:"201806/20180521 How to Install and Configure KVM on Ubuntu 18.04 LTS Server.md"};function c(h,s,g,b,k,m){const n=p("Link");return r(),o("div",null,[s[18]||(s[18]=d(`<h1 id="如何在-ubuntu-18-04-服務器上安裝和配置-kvm" tabindex="-1">如何在 Ubuntu 18.04 服務器上安裝和配置 KVM <a class="header-anchor" href="#如何在-ubuntu-18-04-服務器上安裝和配置-kvm" aria-label="Permalink to “如何在 Ubuntu 18.04 服務器上安裝和配置 KVM”">​</a></h1><p><strong>KVM</strong>（基於內核的虛擬機）是一款為類 Linux 系統提供的開源的全虛擬化解決方案，KVM 使用虛擬化擴展（如 <strong>Intel VT</strong> 或 <strong>AMD-V</strong>）提供虛擬化功能。無論何時我們在任何 Linux 機器上安裝 KVM，都會通過加載諸如 <code>kvm-intel.ko</code>（基於 Intel 的機器）和 <code>kvm-amd.ko</code>（基於 amd 的機器）的內核模組，使其成為<ruby>管理程序<rt>hyervisor</rt></ruby>（LCTT 譯註：一種監控和管理虛擬機運行的核心軟件層）。</p><p>KVM 允許我們安裝和運行多個虛擬機（Windows 和 Linux）。我們可以通過 <code>virt-manager</code> 的圖形用户界面或使用 <code>virt-install</code> 和 <code>virsh</code> 命令在命令列界面來創建和管理基於 KVM 的虛擬機。</p><p>在本文中，我們將討論如何在 Ubuntu 18.04 LTS 服務器上安裝和配置 <strong>KVM 管理程序</strong>。我假設你已經在你的服務器上安裝了 Ubuntu 18.04 LTS 。接下來登錄到您的服務器執行以下步驟。</p><h3 id="第一步-確認您的硬件是否支持虛擬化" tabindex="-1">第一步：確認您的硬件是否支持虛擬化 <a class="header-anchor" href="#第一步-確認您的硬件是否支持虛擬化" aria-label="Permalink to “第一步：確認您的硬件是否支持虛擬化”">​</a></h3><p>執行 <code>egrep</code> 命令以驗證您的服務器的硬件是否支持虛擬化，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ egrep -c &#39;(vmx|svm)&#39; /proc/cpuinfo</span></span>
<span class="line"><span>1</span></span></code></pre></div><p>如果輸出結果大於 0，就意味着您的硬件支持虛擬化。重啓，進入 BIOS 設置中啓用 VT 技術。</p><p>現在使用下面的命令安裝 <code>kvm-ok</code> 實用程序，該程序用於確定您的服務器是否能夠運行硬件加速的 KVM 虛擬機。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo apt install cpu-checker</span></span></code></pre></div><p>運行 kvm-ok 命令確認輸出結果，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo kvm-ok</span></span>
<span class="line"><span>INFO: /dev/kvm exists</span></span>
<span class="line"><span>KVM acceleration can be used</span></span></code></pre></div><h3 id="第二步-安裝-kvm-及其依賴包" tabindex="-1">第二步：安裝 KVM 及其依賴包 <a class="header-anchor" href="#第二步-安裝-kvm-及其依賴包" aria-label="Permalink to “第二步：安裝 KVM 及其依賴包”">​</a></h3><p>運行下面的 apt 命令安裝 KVM 及其依賴項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo apt update</span></span>
<span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo apt install qemu qemu-kvm libvirt-bin  bridge-utils  virt-manager</span></span></code></pre></div><p>只要上圖相應的軟件包安裝成功，那麼你的本地用户（對於我來説是 <code>linuxtechi</code>）將被自動添加到 <code>libvirtd</code> 羣組。</p><h3 id="第三步-啓動並啓用-libvirtd-服務" tabindex="-1">第三步：啓動並啓用 libvirtd 服務 <a class="header-anchor" href="#第三步-啓動並啓用-libvirtd-服務" aria-label="Permalink to “第三步：啓動並啓用 libvirtd 服務”">​</a></h3><p>我們在 Ubuntu 18.04 服務器上安裝 qemu 和 libvirtd 軟件包之後，它就會自動啓動並啓用 <code>libvirtd</code> 服務，如果 <code>libvirtd</code> 服務沒有開啓，則運行以下命令開啓，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo service libvirtd start</span></span>
<span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo update-rc.d libvirtd enable</span></span></code></pre></div><p>現在使用下面的命令確認 libvirtd 服務的狀態，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ service libvirtd status</span></span></code></pre></div><p>輸出結果如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/libvirtd-command-ubuntu18-04.jpg" alt=""></p><h3 id="第四步-為-kvm-虛擬機配置橋接網絡" tabindex="-1">第四步：為 KVM 虛擬機配置橋接網絡 <a class="header-anchor" href="#第四步-為-kvm-虛擬機配置橋接網絡" aria-label="Permalink to “第四步：為 KVM 虛擬機配置橋接網絡”">​</a></h3><p>只有通過橋接網絡，KVM 虛擬機才能訪問外部的 KVM 管理程序或主機。在Ubuntu 18.04中，網絡由 <code>netplan</code> 實用程序管理，每當我們新安裝一個 Ubuntu 18.04 系統時，會自動創建一個名稱為 <code>/etc/netplan/50-cloud-init.yaml</code> 文件，其配置了靜態 IP 和橋接網絡，<code>netplan</code> 實用工具將引用這個文件。</p><p>截至目前，我已經在此文件配置了靜態 IP，文件的具體內容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>network:</span></span>
<span class="line"><span>  ethernets:</span></span>
<span class="line"><span>    ens33:</span></span>
<span class="line"><span>      addresses: [192.168.0.51/24]</span></span>
<span class="line"><span>      gateway4: 192.168.0.1</span></span>
<span class="line"><span>      nameservers:</span></span>
<span class="line"><span>        addresses: [192.168.0.1]</span></span>
<span class="line"><span>      dhcp4: no</span></span>
<span class="line"><span>      optional: true</span></span>
<span class="line"><span>  version: 2</span></span></code></pre></div><p>我們在這個文件中添加橋接網絡的配置信息，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo vi /etc/netplan/50-cloud-init.yaml</span></span>
<span class="line"><span></span></span>
<span class="line"><span>network:</span></span>
<span class="line"><span>  version: 2</span></span>
<span class="line"><span>  ethernets:</span></span>
<span class="line"><span>    ens33:</span></span>
<span class="line"><span>      dhcp4: no</span></span>
<span class="line"><span>      dhcp6: no</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  bridges:</span></span>
<span class="line"><span>    br0:</span></span>
<span class="line"><span>      interfaces: [ens33]</span></span>
<span class="line"><span>      dhcp4: no</span></span>
<span class="line"><span>      addresses: [192.168.0.51/24]</span></span>
<span class="line"><span>      gateway4: 192.168.0.1</span></span>
<span class="line"><span>      nameservers:</span></span>
<span class="line"><span>        addresses: [192.168.0.1]</span></span></code></pre></div><p>正如你所看到的，我們已經從接口（<code>ens33</code>）中刪除了 IP 地址，並將該 IP 添加到 <code>br0</code> 中，並且還將接口（<code>ens33</code>）添加到 <code>br0</code>。使用下面的 <code>netplan</code> 命令使更改生效，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo netplan apply</span></span></code></pre></div><p>如果您想查看 debug 日誌請使用以下命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo netplan --debug  apply</span></span></code></pre></div><p>現在使用以下方法確認網絡橋接狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo networkctl status -a</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/networkctl-command-output-ubuntu18-04.jpg" alt=""></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ ifconfig</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/ifconfig-command-output-ubuntu18-04.jpg" alt=""></p><h3 id="第五步-創建虛擬機-使用-virt-manager-或-virt-install-命令" tabindex="-1">第五步：創建虛擬機（使用 virt-manager 或 virt-install 命令） <a class="header-anchor" href="#第五步-創建虛擬機-使用-virt-manager-或-virt-install-命令" aria-label="Permalink to “第五步：創建虛擬機（使用 virt-manager 或 virt-install 命令）”">​</a></h3><p>有兩種方式創建虛擬機：</p><ul><li><code>virt-manager</code>（圖形化工具）</li><li><code>virt-install</code>（命令列工具）</li></ul><h4 id="使用-virt-manager-創建虛擬機" tabindex="-1">使用 virt-manager 創建虛擬機 <a class="header-anchor" href="#使用-virt-manager-創建虛擬機" aria-label="Permalink to “使用 virt-manager 創建虛擬機”">​</a></h4><p>通過執行下面的命令啓動 <code>virt-manager</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo virt-manager</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/Start-Virt-Manager-Ubuntu18-04.jpg" alt=""></p><p>創建一個新的虛擬機：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/ISO-file-Virt-Manager.jpg" alt=""></p><p>點擊“下一步”然後選擇 ISO 鏡像文件，我使用的是 RHEL 7.3 iso 鏡像。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/Select-ISO-file-virt-manager-Ubuntu18-04-Server.jpg" alt=""></p><p>點擊“下一步”。</p><p>在接下來的幾個窗口中，系統會提示要求您為 VM 分配內存，處理器數量和磁盤空間。</p><p>並指定虛擬機名字和橋接網絡名：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/VM-Name-Network-Virt-Manager-Ubuntu18-04.jpg" alt=""></p><p>點擊“結束”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/RHEL7-3-Installation-Virt-Manager.jpg" alt=""></p><p>接下來只需要按照屏幕指示安裝系統。</p><h4 id="使用virt-install命令從命令列界面創建虛擬機" tabindex="-1">使用virt-install命令從命令列界面創建虛擬機 <a class="header-anchor" href="#使用virt-install命令從命令列界面創建虛擬機" aria-label="Permalink to “使用virt-install命令從命令列界面創建虛擬機”">​</a></h4><p>使用下面的 <code>virt-install</code> 命令從終端創建一個虛擬機，它將在命令列界面中開始安裝，並根據您對虛擬機的名字，説明，ISO 文件位置和橋接配置的設置創建虛擬機。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo virt-install  -n DB-Server  --description &quot;Test VM for Database&quot;  --os-type=Linux  --os-variant=rhel7  --ram=1096  --vcpus=1  --disk path=/var/lib/libvirt/images/dbserver.img,bus=virtio,size=10  --network bridge:br0 --graphics none  --location /home/linuxtechi/rhel-server-7.3-x86_64-dvd.iso --extra-args console=ttyS0</span></span></code></pre></div><p>本文到此為止，我希望這篇文章能幫助你能夠在 Ubuntu 18.04 服務器上成功安裝 KVM。 除此之外，KVM 也是 Openstack 默認的管理程序。</p>`,60)),t("p",null,[s[1]||(s[1]=a("閲讀更多：“",-1)),i(n,{href:"https://www.linuxtechi.com/create-revert-delete-kvm-virtual-machine-snapshot-virsh-command/"},{default:e(()=>[...s[0]||(s[0]=[t("strong",null,"如何使用 virsh 命令創建，還原和刪除 KVM 虛擬機快照",-1)])]),_:1}),s[2]||(s[2]=a("”",-1))]),s[19]||(s[19]=t("hr",null,null,-1)),t("p",null,[s[4]||(s[4]=a("via: ",-1)),i(n,{href:"https://www.linuxtechi.com/install-configure-kvm-ubuntu-18-04-server/"},{default:e(()=>[...s[3]||(s[3]=[a("https://www.linuxtechi.com/install-configure-kvm-ubuntu-18-04-server/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=a("作者：",-1)),i(n,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...s[5]||(s[5]=[a("Pradeep Kumar",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),i(n,{href:"https://github.com/wyxplus"},{default:e(()=>[...s[7]||(s[7]=[a("wyxplus",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const w=l(u,[["render",c]]);export{x as __pageData,w as default};
